import {
  CollectorAdapter,
  ScrapedListing,
  VehicleProfile,
  matchesTrimFilter,
  sleep,
  jitter,
} from "./base";

// Visor.vin — official public listings API (https://api.visor.vin/docs).
// Visor aggregates listings across cars.com, Autotrader, dealer sites, etc.,
// so this source fills gaps left by our own direct scrapers (notably
// cars.com, which has been unreachable — see robots.txt disallow on
// /shopping/results/). Requires VISOR_API_KEY (Bearer token, generated by
// the account owner at visor.vin — never hardcode or share this key).

const API_BASE = "https://api.visor.vin/v1";
const PAGE_SIZE = 100;
// Safety cap so a misconfigured profile / runaway pagination can't loop forever.
const MAX_RECORDS = 1000;

interface VisorListing {
  id: string;
  vin: string;
  year: number | null;
  trim: string | null;
  version: string | null;
  body_type: string | null;
  drivetrain: string | null;
  transmission: string | null;
  price: number | null;
  miles: number | null;
  days_on_market: number | null;
  vdp_url: string | null;
  dealer_name: string | null;
  city: string | null;
  state: string | null;
  exterior_color: string | null;
  interior_color: string | null;
  photo_urls: string[] | null;
  stock_number: string | null;
}

interface VisorListingsResponse {
  data: VisorListing[];
  pagination?: { limit: number; offset: number; total: number; next_offset: number | null };
}

function buildYearList(yearMin: number, yearMax: number): string {
  const years: number[] = [];
  for (let y = yearMin; y <= yearMax; y++) years.push(y);
  return years.join(",");
}

export class VisorCollector implements CollectorAdapter {
  readonly sourceName = "visor";
  private readonly profile: VehicleProfile;

  constructor(profile: VehicleProfile) {
    this.profile = profile;
  }

  async collect(): Promise<ScrapedListing[]> {
    const apiKey = process.env.VISOR_API_KEY;
    if (!apiKey) {
      throw new Error(`[visor:${this.profile.key}] VISOR_API_KEY is not configured — source unavailable`);
    }

    const make = this.profile.visorMake ?? this.profile.makeDisplay;
    const model = this.profile.visorModel ?? this.profile.modelDisplay;
    const year = buildYearList(this.profile.yearMin, this.profile.yearMax);

    const raw: VisorListing[] = [];
    let offset = 0;
    let total = Infinity;

    while (offset < total && offset < MAX_RECORDS) {
      const params = new URLSearchParams({
        make,
        model,
        year,
        limit: String(PAGE_SIZE),
        offset: String(offset),
        inventory_status: "active",
      });
      if (this.profile.maxPrice) {
        params.set("max_price", String(this.profile.maxPrice));
      }

      const url = `${API_BASE}/listings?${params.toString()}`;
      console.log(`[visor:${this.profile.key}] Fetching offset ${offset}: ${url}`);

      let res: Response;
      try {
        res = await fetch(url, {
          headers: { Authorization: `Bearer ${apiKey}` },
        });
      } catch (err) {
        throw new Error(`[visor:${this.profile.key}] Fetch failed: ${err}`);
      }

      if (!res.ok) {
        if (offset === 0) {
          const body = await res.text().catch(() => "");
          throw new Error(`HTTP ${res.status} on first page — source unavailable. ${body.slice(0, 200)}`);
        }
        console.warn(`[visor:${this.profile.key}] HTTP ${res.status} at offset ${offset}, stopping`);
        break;
      }

      const json = (await res.json()) as VisorListingsResponse;
      const page = json.data ?? [];
      raw.push(...page);
      total = json.pagination?.total ?? page.length;

      console.log(`[visor:${this.profile.key}] offset ${offset}: ${page.length} raw (total ${total})`);

      if (page.length === 0) break;
      offset += PAGE_SIZE;

      if (offset < total) {
        await sleep(jitter(300, 200));
      }
    }

    console.log(`[visor:${this.profile.key}] Total raw: ${raw.length}`);

    const matched = raw
      .map((item) => this.toScrapedListing(item))
      .filter((l): l is ScrapedListing => l !== null);

    console.log(`[visor:${this.profile.key}] ${matched.length} listings matched profile`);

    return this.dedup(matched);
  }

  private toScrapedListing(item: VisorListing): ScrapedListing | null {
    if (!item.price) return null;
    // Skip rather than fabricate a detail-page URL when Visor doesn't have one on file.
    if (!item.vdp_url) return null;

    const trim = item.trim ?? undefined;
    const title = `${item.year ?? ""} ${this.profile.makeDisplay} ${this.profile.modelDisplay}${trim ? " " + trim : ""}`.trim();
    // Include version + body_type in the matchable text — Visor's "trim" field
    // is sometimes narrower than what our substring filters expect (e.g. the
    // C63 S E Performance shows up with version "AMG C63 S E Peformance 4MATIC").
    const matchableText = `${title} ${item.version ?? ""} ${item.body_type ?? ""}`;

    if (this.profile.trimFilter) {
      if (!matchesTrimFilter(this.profile.trimFilter, trim, matchableText)) {
        return null;
      }
    }

    if (this.profile.excludeKeywords?.length) {
      if (this.profile.excludeKeywords.some((kw) => matchesTrimFilter(kw, trim, matchableText))) {
        return null;
      }
    }

    const location = item.city && item.state ? `${item.city}, ${item.state}` : undefined;

    const rawTx = (item.transmission ?? "").toLowerCase();
    const transmissionText: "manual" | "automatic" | undefined =
      rawTx.includes("manual")
        ? "manual"
        : rawTx.includes("auto") || rawTx.includes("pdk") || rawTx.includes("tiptronic")
          ? "automatic"
          : undefined;

    return {
      externalId: item.id,
      url: item.vdp_url,
      title,
      year: item.year ?? this.profile.yearMin,
      make: this.profile.makeDisplay,
      model: this.profile.modelDisplay,
      trim,
      askingPrice: item.price,
      mileage: item.miles ?? undefined,
      location,
      sellerName: item.dealer_name ?? undefined,
      exteriorColor: item.exterior_color ?? undefined,
      interiorColor: item.interior_color ?? undefined,
      imageUrl: item.photo_urls?.[0],
      vin: item.vin,
      stockId: item.stock_number ?? undefined,
      sourceDaysOnMarket: item.days_on_market ?? undefined,
      transmissionText,
      rawPayload: item as unknown as Record<string, unknown>,
    };
  }

  private dedup(listings: ScrapedListing[]): ScrapedListing[] {
    const seen = new Set<string>();
    return listings.filter((l) => {
      if (seen.has(l.url)) return false;
      seen.add(l.url);
      return true;
    });
  }
}
